// Format: "Starting '<agent-type>' agent: <description> (<tool-use-id>)"
//
// Edge cases:
//   - Empty description: "Starting '<agent-type>' agent (<tool-use-id>)"
//   - Empty agentType: "Starting agent: <description> (<tool-use-id>)"
