			agentType:   "",
			description: "Implement user authentication",
			toolUseID:   "toolu_019t1c",
			want:        "Starting agent: Implement user authentication (toolu_019t1c)",
		},
		{
			name:        "both empty",
			agentType:   "",
			description: "",
			toolUseID:   "toolu_019t1c",
			want:        "Task: toolu_019t1c",
		},
